<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {useUserStore} from '@/stores/user'
import type {SampleLabel} from '@/types/sampleManagement'
import {MAX_LABEL_COPIES,printableSampleLabels,sampleQrDataUrl,type PreparedLabel} from '@/utils/sampleLabels'
const props=defineProps<{modelValue:boolean;samples:SampleLabel[]}>(),emit=defineEmits<{'update:modelValue':[value:boolean]}>()
const user=useUserStore(),width=ref(60),height=ref(50),prepared=ref<PreparedLabel[]>([]),copies=ref<Record<number,number>>({}),loading=ref(false),error=ref(''),overflow=ref(false),preview=ref<HTMLElement>(),printing=ref(false)
const total=computed(()=>prepared.value.reduce((sum,row)=>sum+(copies.value[row.sample.sampleIdentityId]||0),0))
let epoch=0,frame:HTMLIFrameElement|undefined
async function prepare(){const ticket=++epoch,auth=user.token;prepared.value=[];error.value='';overflow.value=false;if(!props.modelValue)return;loading.value=true;try{const unique=[...new Map(props.samples.map(s=>[s.sampleIdentityId,s])).values()];if(unique.length>MAX_LABEL_COPIES)throw new Error('单次最多选择200种样品，请分批打印');for(const s of unique)copies.value[s.sampleIdentityId]??=1;const labels=await Promise.all(unique.map(async sample=>({sample,qr:await sampleQrDataUrl(sample.sampleCode,window.location.origin),copies:copies.value[sample.sampleIdentityId]||1})));if(ticket===epoch&&auth===user.token){prepared.value=labels;await measure()}}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'二维码生成失败，请重试'}finally{if(ticket===epoch)loading.value=false}}
async function measure(){await nextTick();overflow.value=!!preview.value&&Array.from(preview.value.querySelectorAll('.label-preview')).some(node=>node.getBoundingClientRect().height>height.value*96/25.4+1)}
watch(()=>[props.modelValue,props.samples],prepare,{immediate:true,deep:true});watch([width,height],measure)
watch(()=>user.token,()=>{++epoch;prepared.value=[];copies.value={};error.value='';emit('update:modelValue',false);frame?.remove()})
async function print(){if(loading.value||overflow.value||!prepared.value.length)return;error.value='';const auth=user.token;printing.value=true;try{const html=printableSampleLabels(prepared.value.map(row=>({...row,copies:copies.value[row.sample.sampleIdentityId]||0})),width.value,height.value);frame?.remove();frame=document.createElement('iframe');frame.title='样品标签打印';frame.style.cssText='position:fixed;width:0;height:0;border:0;bottom:0;left:0';document.body.appendChild(frame);const target=frame;await new Promise<void>((resolve,reject)=>{target.onload=()=>resolve();target.onerror=()=>reject(new Error('打印预览未能载入'));target.srcdoc=html});if(auth!==user.token||!props.modelValue)return;const win=target.contentWindow;if(!win)throw new Error('浏览器不支持打印预览');await Promise.all(Array.from(win.document.images).map(img=>img.complete?Promise.resolve():new Promise<void>(resolve=>{img.onload=()=>resolve();img.onerror=()=>resolve()})));if(auth!==user.token||!props.modelValue)return;win.focus();win.print()}catch(e){error.value=e instanceof Error?e.message:'打印预览失败'}finally{printing.value=false}}
onBeforeUnmount(()=>{++epoch;frame?.remove()})
</script>
<template><el-dialog class="sample-label-print-dialog" :model-value="modelValue" :title='uiText("打印样品标签")' width="min(980px,96vw)" append-to-body :close-on-click-modal="false" @update:model-value="emit('update:modelValue',$event)"><div class="label-print" v-loading="loading"><div class="label-settings"><label>{{ uiText("宽度 mm") }}<el-input-number v-model="width" :min="30" :max="150" :precision="0" size="small"/></label><label>{{ uiText("高度 mm") }}<el-input-number v-model="height" :min="30" :max="200" :precision="0" size="small"/></label><span>{{ uiText("默认 60 × 50 mm · 每页一张标签") }}</span></div><p>{{ uiText("同种样品使用同一个码。标签份数只用于打印，不改变实物数量。") }}</p><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="prepare">{{ uiText("重试") }}</el-button></el-alert><el-alert v-if="overflow" :title='uiText("内容超出当前标签高度，请调大尺寸后打印；文字完整保留。")' type="warning" :closable="false"/><div ref="preview" class="label-preview-list"><article v-for="row in prepared" :key="row.sample.sampleIdentityId" class="label-preview-item"><div class="label-preview" :style="{width:width+'mm',minHeight:height+'mm'}"><strong class="label-code">{{row.sample.sampleCode}}</strong><div class="label-content"><img :src="row.qr" :alt="row.sample.sampleCode+'二维码'" @load="measure"><div class="label-words"><strong>{{row.sample.productName||row.sample.name}}</strong><div v-if="row.sample.supplierName">{{ uiText("供应商：") }}{{row.sample.supplierName}}</div><div>{{row.sample.phoneName||row.sample.specName}}</div><div>{{[row.sample.colorName,row.sample.sampleVersion].filter(Boolean).join(' · ')}}</div></div></div></div><label class="label-copies">{{row.sample.sampleCode}}{{ uiText(" · 标签份数") }}<el-input-number v-model="copies[row.sample.sampleIdentityId]" :min="1" :max="MAX_LABEL_COPIES" :precision="0" size="small"/></label></article></div><p v-if="!prepared.length&&!loading">{{ uiText("请选择已有样品码后打印。") }}</p></div><template #footer><span class="label-total">{{ uiText("共 ") }}{{total}}{{ uiText(" 张（单次最多 ") }}{{MAX_LABEL_COPIES}}{{ uiText(" 张）") }}</span><el-button @click="emit('update:modelValue',false)">{{ uiText("关闭") }}</el-button><el-button type="primary" :loading="printing" :disabled="loading||overflow||!prepared.length||total<1||total>MAX_LABEL_COPIES" @click="print">{{ uiText("打开浏览器打印预览") }}</el-button></template></el-dialog></template>
<style scoped>.label-print{font-size:12px;min-width:0}.label-settings{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.label-settings label,.label-copies{display:flex;flex-direction:column;gap:4px;color:#536b87}.label-settings span,.label-total{font-size:12px;color:#75859b}.label-preview-list{display:flex;gap:16px;flex-wrap:wrap;max-height:55vh;overflow:auto;margin:12px 0}.label-preview-item{max-width:100%;min-width:0}.label-preview{border:1px solid #cbd5e2;padding:2mm;box-sizing:border-box;background:white;color:black;max-width:100%}.label-code{display:block;font-size:12pt;line-height:1.25;overflow-wrap:anywhere}.label-content{display:flex;align-items:flex-start;gap:1mm;margin-top:1mm}.label-content img{width:24mm;height:24mm;flex:none}.label-words{font-size:8pt;line-height:1.3;min-width:0;overflow-wrap:anywhere}.label-words strong{font-size:9pt}.label-copies{margin-top:8px;font-size:12px}.label-total{margin-right:auto}.label-print :deep(.el-input-number){height:28px}.label-print :deep(.el-input__wrapper){font-size:12px}:global(.sample-label-print-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-top:20px;margin-bottom:20px;overflow:hidden}:global(.sample-label-print-dialog>.el-dialog__header),:global(.sample-label-print-dialog>.el-dialog__footer){flex:none}:global(.sample-label-print-dialog>.el-dialog__body){min-height:0;overflow:auto}
</style>
